import json,re
P="C:/visual projects/wol-study/docs/spec/"
b=open(P+"15b-relics-catalog.md",encoding='utf-8').read().split('\n')
m=open(P+"15-relics.md",encoding='utf-8').read().split('\n')
ren=[("комплект странника","набор сигнатуры"),("«лёд-пламя»","«морозный жар»"),("«странник»","«сигнатурный набор»"),("«выпускник»","«казна»"),("«фокусник»","«усиление умений»"),("«вампир»","«кровосток»"),("«единорог»","«радуга»")]
man={
 "амулет: шанс спастись от смертельного удара":"амулет: убывающий шанс пережить смертельный удар",
 "проклятие хаба: враги хрупче, но бьют сильнее":"проклятие хаба: у врагов меньше HP, но больше урона",
 "проклятие хаба: любой удар = 99 урона":"проклятие хаба: каждый нестатусный удар фиксирован на 99",
 "Плюс: враги умирают с одного удара; Минус: игрок тоже.":"Итог: любое попадание убивает любого участника, включая самого игрока.",
 "проклятие хаба: врагов вдвое больше":"проклятие хаба: вдвое больше противников, но слабее",
 "Плюс: здоровье врагов −20% (множ.). Минус: число врагов на уровнях удваивается (флаг уровня).":"Здоровье врагов −20% (множ.) в обмен на удвоенное число врагов на уровне (флаг уровня).",
 "проклятие: x2 реликвий в дропе, -50% золота":"проклятие: дроп реликвий ×2 при золоте −50%",
 "Плюс: взрыв бочек вредит только врагам, игрок неуязвим к ним; Минус: длительность оглушения игроков при ударах +75% (множ.).":"Плюс: взрывы бочек бьют лишь врагов, владелец от них не страдает; Минус: оглушение владельца от попаданий длится на 75% дольше (множ.).",
}
out_b=[];out_m=[]
for n in range(360,532):
    l=b[n-1]; new=l
    if l.startswith('|') and ('Р' in l[:6]):
        for k,v in man.items(): new=new.replace(k,v)
        for k,v in ren: new=new.replace(k,v)
        if n==489: new=l
    if new!=l: out_b.append({"old":l,"new":new})
for n,l in enumerate(m,1):
    new=l
    if n==207:
        new=l.replace("лёд-пламя","морозный жар").replace("странник","сигнатурный набор").replace("выпускник","казна").replace("фокусник","усиление умений").replace("вампир","кровосток").replace("единорог","радуга")
    if new!=l: out_m.append({"old":l,"new":new})
for lst,f in((out_b,"15b_part3.json"),(out_m,"15_main.json")):
    assert len({x['old'] for x in lst})==len(lst)
    json.dump(lst,open("patches/"+f,'w',encoding='utf-8'),ensure_ascii=False,indent=1)
print(len(out_b),len(out_m))
for x in out_b[:30]: print(x['old'][:60],'=>',[w for w in re.findall(r'«[^»]+»',x['new'])][:3])
for l in (b,m):
    pass
# uniqueness check against file
full=open(P+"15b-relics-catalog.md",encoding='utf-8').read().split('\n')
for x in out_b: assert full.count(x['old'])==1
for x in out_m: assert m.count(x['old'])==1
EOF
python mk.py; grep -c "" patches/*.json

